    {"automation-science-pack", 100, 0},
}

-- Up to 8 infinity chests on each boss defeat
local reward_settings = {
    {
        position_offset = { x = 32, y = 32 },
        chance = { 100, 100, 100, 100, 100 },
    },
    {
        position_offset = { x = -32, y = -32 },
        chance = { 0, 50, 100, 100, 100 },
